function validate([divisor1, divisor2, uniqueCnt1, uniqueCnt2]) {
  const whole = v => Number.isInteger(v);
  if (![divisor1, divisor2].every(d => whole(d) && d >= 2 && d <= 100000)) return 'Both divisors are integers from 2 to 100000.';
  if (![uniqueCnt1, uniqueCnt2].every(c => whole(c) && c >= 1 && c < 1000000000)) return 'Each count is an integer from 1 to 999999999.';
  if (uniqueCnt1 + uniqueCnt2 > 1000000000) return 'The two counts add up to at most 10^9.';
  return null;
}

