function minimizeSet(divisor1, divisor2, uniqueCnt1, uniqueCnt2) {
  let a = divisor1;
  let b = divisor2;
  while (b !== 0) {
    [a, b] = [b, a % b];
  }
  const lcm = (divisor1 / a) * divisor2;
  const canFit = (limit) => {
    const forFirst = limit - Math.floor(limit / divisor1);
    const forSecond = limit - Math.floor(limit / divisor2);
    const forEither = limit - Math.floor(limit / lcm);
    return forFirst >= uniqueCnt1 && forSecond >= uniqueCnt2 && forEither >= uniqueCnt1 + uniqueCnt2;
  };
  let low = 1;
  let high = 2 * (uniqueCnt1 + uniqueCnt2);
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (canFit(mid)) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

