function minimizeSet(divisor1, divisor2, uniqueCnt1, uniqueCnt2) {
  // Closed form, no search: the c-th positive integer that is not a multiple of d is c + floor((c - 1) / (d - 1)),
  // because each block of d consecutive integers holds d - 1 of them. The answer is the largest of three such thresholds:
  // arr1's own needs, arr2's own needs, and both lists' needs among integers that are not multiples of the lcm.
  const gcd = (x, y) => (y === 0 ? x : gcd(y, x % y));
  const lcm = divisor1 / gcd(divisor1, divisor2) * divisor2;
  const nth = (d, c) => c + Math.floor((c - 1) / (d - 1));
  return Math.max(nth(divisor1, uniqueCnt1), nth(divisor2, uniqueCnt2), nth(lcm, uniqueCnt1 + uniqueCnt2));
}

