function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const r = rand();
    const divisor1 = r < 0.3 ? pick(2, 6) : pick(2, 100000);
    const divisor2 = r < 0.15 ? divisor1 : r < 0.3 ? divisor1 * pick(1, 4) : pick(2, 100000);
    const total = pick(500000000, 1000000000);
    const uniqueCnt1 = pick(1, total - 1);
    return [divisor1, Math.min(divisor2, 100000), uniqueCnt1, total - uniqueCnt1];
  }
  const divisor1 = pick(2, 8);
  const divisor2 = rand() < 0.25 ? divisor1 : pick(2, 8);
  return [divisor1, divisor2, pick(1, 20), pick(1, 20)];
}
